head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getChildren]<br/>options.excludePlugin, options.includePlugin 파라미터를 검증합니다.",
    "validation" : [
        "options.excludePlugin 으로 제외할 Plugin 이름 목록을 공백으로 구분하여 설정할 수 있어야 합니다.",
        "options.includePlugin 으로 포함할 Plugin 이름 목록을 공백으로 구분하여 설정할 수 있어야 합니다.",
        "excludePlugin 과 includePlugin 에 동시에 설정된 컴포넌트는 제외되어야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof grp_test !== 'undefined') {
        grp_test.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // grp_test: 다양한 타입의 자식 컴포넌트를 가진 그룹
    let strGrpTest = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_test = await $p.dynamicCreate('grp_test', 'group', strGrpTest, grp_comp);

    let strTxt1 = '<w2:textbox ' + ns + ' label="텍스트1" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child1', 'textbox', strTxt1, scwin.grp_test);

    let strTxt2 = '<w2:textbox ' + ns + ' label="텍스트2" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child2', 'textbox', strTxt2, scwin.grp_test);

    let strBtn = '<w2:button ' + ns + ' label="버튼1" style=""></w2:button>';
    await $p.dynamicCreate('btn_child1', 'button', strBtn, scwin.grp_test);

    let strOutput = '<xf:output ' + ns + ' label="output" style="width:200px;height:50px;background-color:var(--ws-gray-300);"></xf:output>';
    await $p.dynamicCreate('output_child1', 'output', strOutput, scwin.grp_test);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getChildren_onclick = function () {
    let excludePluginVal = par_excludePlugin.getValue();
    let includePluginVal = par_includePlugin.getValue();

    let options = { recursive : false };
    if (excludePluginVal !== '') {
        options.excludePlugin = excludePluginVal;
    }
    if (includePluginVal !== '') {
        options.includePlugin = includePluginVal;
    }

    let ret = WebSquare.util.getChildren(grp_test, options);

    let result = [];
    result.push("자식 수: " + ret.length);

    for (let i = 0; i < ret.length; i++) {
        result.push("[" + i + "] id: " + ret[i].getID());
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
